const snippets={"Python": ["from typing import List, Optional", "", "class Solution:", "", "    def buildTree(self, preorder: List[int], inorder: List[int]) -> Optional[TreeNode]:", "", "        def dfs(i: int, j: int, n: int) -> Optional[TreeNode]:", "            if n <= 0:", "                return None", "            v = preorder[i]", "            k = d[v]", "            l = dfs(i + 1, j, k - j)", "            r = dfs(i + 1 + k - j, k + 1, n - k + j - 1)", "            return TreeNode(v, l, r)", "        d = {v: i for (i, v) in enumerate(inorder)}", "        return dfs(0, 0, len(preorder))"], "Java": ["import java.util.*;", "class Solution {", "    private int[] preorder;", "    private Map<Integer, Integer> d = new HashMap<>();", "", "    public TreeNode buildTree(int[] preorder, int[] inorder) {", "        int n = preorder.length;", "        this.preorder = preorder;", "        for (int i = 0; i < n; ++i) {", "            d.put(inorder[i], i);", "        }", "        return dfs(0, 0, n);", "    }", "", "    private TreeNode dfs(int i, int j, int n) {", "        if (n <= 0) {", "            return null;", "        }", "        int v = preorder[i];", "        int k = d.get(v);", "        TreeNode l = dfs(i + 1, j, k - j);", "        TreeNode r = dfs(i + 1 + k - j, k + 1, n - 1 - (k - j));", "        return new TreeNode(v, l, r);", "    }", "}"]};
